import React from 'react';
import './Projects.css'

import ProjectCard from '../../components/ProjectCard/ProjectCard';
import svt from '../../assets/images/img-svt-declaration.png'
import avati from '../../assets/images/img-avati.png'
import natullie from '../../assets/images/img-natullie.png'
import cs from '../../assets/images/img-cs.jpeg'
import abrange from '../../assets/images/img-abrange.png'
import solar from '../../assets/images/img-solar.png'
import vitu from '../../assets/images/img-vitu.png'

const Projects = () => {
  return (
    <div id='projects'>
      <div className='title-container'>
        <h2 className='section-title'>Projetos</h2>
        <div className='icons-container'>
            <i className="bi bi-circle-half"></i>
            <i className="bi bi-brightness-high-fill"></i>
            <i className="bi bi-bullseye"></i>
        </div>
      </div>
      <div className='projects-cards-container'>
        <ProjectCard
          title="Declaração de autenticidade de certificado"
          tools="React.js, Firebase, Node.js CraTemplate, ReactDom, Git"
          liveDemoLink="https://declaracao.svtfaculdade.edu.br/"
          image={svt}
        />
        <ProjectCard
          title="Tecnovão - Login em banco de dados fictício"
          tools="ReactJs, Git"
          liveDemoLink="https://victorgabrielmds.github.io/desafio-login-avati/"
          image={avati}
        />
        <ProjectCard
          title="Convite Web - Exemplo"
          tools="ReactJs, Firebase, FramerMotion, ReactDom"
          liveDemoLink="https://convite-web-cha.web.app/?nome=visitante"
          image={vitu}
        />
        <ProjectCard
          title="Site catálogo Natullie - cadastro e edição interno"
          tools="HTML, Css, JavaScript, Bootstrap,Firebase, Firebase, Git"
          liveDemoLink="https://victorgabrielmds.github.io/natullie/"
          image={natullie}
        />
        <ProjectCard
          title="Rede de parceiro online Cartão Saúde"
          tools="HTML, Css, JavaScript, Bootstrap, Firebase, Git"
          liveDemoLink="https://victorgabrielmds.github.io/siteCartaoSaude"
          image={cs}
        />
        <ProjectCard
          title="Site institucional Abrange"
          tools="HTML, Css, JavaScript, Git"
          liveDemoLink="https://institutoabrange.com.br/"
          image={abrange}
        />
        <ProjectCard
          title="Site de vendas Solar Calçados"
          tools="HTML, Css, JavaScript, TypeScript, Git"
          liveDemoLink="https://institutoabrange.com.br/"
          image={solar}
        />
      </div>
    </div>
  );
};

export default Projects;
